<?php require_once __DIR__.'/verificar_admin.php';require_once __DIR__.'/../config/conexion.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Método no permitido.');}validar_token();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id)ir('index.php');try{$q=$pdo->prepare('DELETE FROM juegos WHERE id_juego=?');$q->execute([$id]);ir('index.php?status=deleted');}catch(PDOException $e){http_response_code(409);exit('No se puede eliminar: existen registros relacionados. <a href="index.php">Volver</a>');}